// Общие шаги для «היו כאן» (#ab0123, #67c751, #ee51bb): окно роли iPhone 13 Mini (WebKit) с эмулированной геолокацией,
// согласие «להפעיל», выключение тумблером, ответы nearby_recent / nearby_places, тап по координатам после ухода сплэша.
// Селекторы и запросы сверены разведкой на живом сайте 04.11 (reg1/reg2, WebKit 375×812).
import { devices, expect, type Browser, type BrowserContext, type Page, type Locator, type Response } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

// Фиктивные координаты (Тель-Авив, ~225 м друг от друга). Реальная геолокация не используется.
export const GEO = {
  reg1: { latitude: 32.0853, longitude: 34.7818 },
  reg2: { latitude: 32.0868, longitude: 34.7802 },
} as const;
export type Role = keyof typeof GEO;
export const NAME = { reg1: 'QA הרשמה, 40', reg2: 'QA הרשמה 2, 30' } as const;
export const WERE_HERE = '/map?tab=were-here';

const cfg = JSON.parse(fs.readFileSync(path.resolve(__dirname, '../../qa.config.json'), 'utf8'));
const BASE = process.env.QA_BASE_URL || cfg.baseUrl;
const authFile = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);

export type RolePage = { role: Role; page: Page; ctx: BrowserContext; id: string };

// id пользователя из .qa/auth/<role>.json.
export function userIdOf(role: string): string {
  const state = JSON.parse(fs.readFileSync(authFile(role), 'utf8'));
  for (const o of state.origins ?? []) for (const kv of o.localStorage ?? []) {
    if (/auth-token/.test(kv.name)) { const id = JSON.parse(kv.value)?.user?.id; if (id) return id; }
  }
  throw new Error(`Нет user.id в .qa/auth/${role}.json — перелогинь роль (qa-login:manual -- ${role})`);
}

// Окно роли: iPhone 13 Mini (WebKit, если браузер WebKit), he-IL, сохранённая сессия, эмулированная геолокация.
export async function openRole(browser: Browser, role: Role): Promise<RolePage> {
  const { defaultBrowserType: _b, ...iphone } = devices['iPhone 13 Mini'];
  const ctx = await browser.newContext({
    ...iphone,
    baseURL: BASE,
    locale: 'he-IL',
    storageState: authFile(role),
    geolocation: { ...GEO[role], accuracy: 10 },
    permissions: ['geolocation'],
  });
  return { role, ctx, page: await ctx.newPage(), id: userIdOf(role) };
}

// Refresh-токен Supabase одноразовый — записать свежую сессию обратно (не затирая пустой).
export async function saveSession(r: RolePage) {
  try {
    const st = await r.ctx.storageState();
    const ok = st.origins.some((o) => o.localStorage.some((kv) => /auth-token/.test(kv.name) && kv.value.includes('refresh_token')));
    if (ok) fs.writeFileSync(authFile(r.role), JSON.stringify(st, null, 2));
  } catch { /* не скрывать результат теста */ }
}

export const consentTitle = (p: Page) => p.getByText('לראות מי היה לידך?');
export const enableBtn = (p: Page) => p.getByRole('button', { name: 'להפעיל', exact: true });
export const shareSwitch = (p: Page) => p.getByRole('switch', { name: 'שיתוף מיקום פעיל' });
export const listTitle = (p: Page) => p.getByText('כל מי שחלף לידך');
export const emptyTitle = (p: Page) => p.getByText('עוד לא חלפו לידך אנשים');
export const card = (p: Page, name: string) => p.getByRole('button', { name, exact: true });

export const isRpc = (fn: string) => (r: Response) => r.url().includes(`/rest/v1/rpc/${fn}`) && r.request().method() === 'POST';
export const isProfilePatch = (r: Response) => r.request().method() === 'PATCH' && r.url().includes('/rest/v1/profiles');

export type State = { nearby_opt_in: boolean; share_location: boolean };

// Открыть «היו כאן» и дождаться окончательного состояния листа по профилю из БД (согласие мелькает до загрузки профиля).
export async function openWereHere(p: Page, id: string, url = WERE_HERE): Promise<State> {
  const { state } = await readState(p, id, url);
  if (state.nearby_opt_in && state.share_location) {
    await expect(listTitle(p).or(emptyTitle(p)).first()).toBeVisible();
  } else {
    await expect(enableBtn(p).or(shareSwitch(p)).first()).toBeVisible();
  }
  return state;
}

// Тап по центру элемента по координатам — только когда сплэш/анимация ушли и в этой точке сам элемент (L-20261102-1).
// touch=true — касание (touchscreen.tap) вместо клика мышью: вложенная кнопка «אהבתי» внутри карточки на клик мышью по координатам не реагирует.
export async function tapWhenTop(p: Page, target: Locator, opts: { touch?: boolean } = {}) {
  await expect(target).toBeVisible();
  // Вьюпорт iPhone 13 Mini — 375×629: нижняя часть листа (сердце карточки) за краем экрана → сначала докрутить.
  await target.scrollIntoViewIfNeeded();
  let pt = { x: 0, y: 0 };
  let prev = '';
  await expect
    .poll(async () => {
      const box = await target.boundingBox();
      if (!box || box.width === 0 || box.height === 0) return false;
      // Лист/карта ещё могут въезжать — тапаем, когда положение не меняется между двумя опросами.
      const key = `${Math.round(box.x)},${Math.round(box.y)},${Math.round(box.width)},${Math.round(box.height)}`;
      const stable = key === prev;
      prev = key;
      // Центр видимой части элемента (низ карточки может уходить за край вьюпорта 629 px).
      const vh = p.viewportSize()?.height ?? 10_000;
      const bottom = Math.min(box.y + box.height, vh);
      pt = { x: box.x + box.width / 2, y: (Math.max(box.y, 0) + bottom) / 2 };
      const top = await target.evaluate((el, { x, y }) => { const e = document.elementFromPoint(x, y); return !!e && (e === el || el.contains(e)); }, pt);
      return stable && top;
    }, { message: 'элемент неподвижен и сверху в точке тапа (сплэш ушёл)', timeout: 20_000, intervals: [250] })
    .toBe(true);
  if (opts.touch) await p.touchscreen.tap(pt.x, pt.y);
  else await p.mouse.click(pt.x, pt.y);
}

// Согласие «להפעיל»: ждёт PATCH nearby_opt_in+share_location=true и лист (список или пусто) без перезагрузки.
export async function consent(r: RolePage) {
  const st = await openWereHere(r.page, r.id);
  if (st.nearby_opt_in && st.share_location) return;
  const patch = r.page.waitForResponse(isProfilePatch);
  await tapWhenTop(r.page, enableBtn(r.page));
  const res = await patch;
  expect(res.ok(), 'PATCH profiles при «להפעיל»').toBeTruthy();
  expect(res.request().postDataJSON()).toMatchObject({ nearby_opt_in: true, share_location: true });
  await expect(listTitle(r.page).or(emptyTitle(r.page)).first()).toBeVisible();
}

export type Api = { base: string; apikey: string; auth: string };

// Открыть страницу, взять адрес API и токен из настоящего запроса приложения, прочитать share_location/nearby_opt_in из БД.
async function readState(p: Page, id: string, url = WERE_HERE): Promise<{ state: State; api: Api }> {
  const req = p.waitForRequest((q) => {
    const h = q.headers();
    return q.url().includes('/rest/v1/') && !!h['apikey'] && !!h['authorization'] && h['authorization'] !== `Bearer ${h['apikey']}`;
  });
  await p.goto(url);
  const q = await req;
  const h = await q.allHeaders();
  const api = { base: q.url().split('/rest/v1/')[0], apikey: h['apikey'], auth: h['authorization'] };
  const res = await p.request.get(`${api.base}/rest/v1/profiles?id=eq.${id}&select=nearby_opt_in,share_location`, {
    headers: { apikey: api.apikey, Authorization: api.auth }, failOnStatusCode: false,
  });
  expect(res.ok(), `profiles state: ${await res.text()}`).toBeTruthy();
  const row = (await res.json())[0];
  return { state: { nearby_opt_in: !!row.nearby_opt_in, share_location: !!row.share_location }, api };
}

// Состояние роли из БД (через токен самой роли).
export async function dbState(r: RolePage): Promise<State> {
  return (await readState(r.page, r.id)).state;
}

// Прямой вызов RPC от имени роли (для проверки «у себя пусто», когда экран согласия списки не запрашивает).
export async function callRpc(r: RolePage, fn: string): Promise<Row[]> {
  const { api } = await readState(r.page, r.id);
  const res = await r.page.request.post(`${api.base}/rest/v1/rpc/${fn}`, {
    headers: { apikey: api.apikey, Authorization: api.auth, 'Content-Type': 'application/json' }, data: {}, failOnStatusCode: false,
  });
  expect(res.status(), `rpc/${fn}: ${await res.text()}`).toBe(200);
  return res.json();
}

// Очистка: выключить участие тумблером (диалог → «כיבוי שיתוף מיקום»); если в БД всё ещё true — вернуть PATCH-ем.
// Итог всегда share_location=false, nearby_opt_in=false. Сессию записать.
export async function turnOff(r: RolePage) {
  if (r.page.isClosed()) return;
  try {
    const st = await openWereHere(r.page, r.id);
    if (st.share_location && (await shareSwitch(r.page).isVisible())) {
      await tapWhenTop(r.page, shareSwitch(r.page));
      const dlg = r.page.getByRole('dialog');
      const patch = r.page.waitForResponse(isProfilePatch);
      await dlg.getByRole('button', { name: 'כיבוי שיתוף מיקום' }).click();
      await patch;
      await expect(consentTitle(r.page)).toBeVisible();
    }
    const { state, api } = await readState(r.page, r.id);
    if (state.nearby_opt_in || state.share_location) {
      const res = await r.page.request.patch(`${api.base}/rest/v1/profiles?id=eq.${r.id}`, {
        headers: { apikey: api.apikey, Authorization: api.auth, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
        data: { share_location: false, nearby_opt_in: false }, failOnStatusCode: false,
      });
      expect(res.ok(), `возврат share_location/nearby_opt_in=false для ${r.role}: ${await res.text()}`).toBeTruthy();
    }
  } finally {
    await saveSession(r);
  }
}

export type Row = Record<string, unknown>;

// Перезагрузить «היו כאן» и вернуть ответы nearby_recent и nearby_places.
export async function reloadLists(p: Page): Promise<{ recent: Row[]; places: Row[] }> {
  const rec = p.waitForResponse(isRpc('nearby_recent'));
  const pl = p.waitForResponse(isRpc('nearby_places'));
  await p.goto(WERE_HERE);
  const [a, b] = await Promise.all([rec, pl]);
  expect(a.status()).toBe(200);
  expect(b.status()).toBe(200);
  return { recent: await a.json(), places: await b.json() };
}

// Опрос: перезагружать лист, пока пользователь id не появится (true) / не исчезнет (false) в nearby_recent.
export async function expectInRecent(p: Page, id: string, present: boolean, timeout = 60_000) {
  await expect
    .poll(async () => (await reloadLists(p)).recent.some((r) => String(r.id) === id), {
      message: `nearby_recent ${present ? 'содержит' : 'не содержит'} ${id}`, timeout, intervals: [2_000, 3_000, 5_000],
    })
    .toBe(present);
}

// Пара рядом: reg2 соглашается первой, затем reg1 — у reg1 в листе карточка reg2.
export async function meetPair(reg1: RolePage, reg2: RolePage) {
  await turnOff(reg1);
  await turnOff(reg2);
  await consent(reg2);
  await consent(reg1);
  await expect(card(reg1.page, NAME.reg2)).toBeVisible();
}

// Раскрыть лист вверх (17.01b) тапом по «ручке» над «כל מי שחלף לידך». На вьюпорте 375×629 сердце первой карточки
// иначе под нижней навигацией. Свайп в WebKit не эмулируется — ручка раскрывает лист по тапу (проверено 04.11).
export async function expandSheet(p: Page) {
  const title = listTitle(p);
  await expect(title).toBeVisible();
  // Лист ещё въезжает после загрузки — ждём неподвижного положения заголовка.
  let prev = -1;
  let y = 0;
  await expect.poll(async () => { y = Math.round((await title.boundingBox())?.y ?? -1); const ok = y === prev && y > 0; prev = y; return ok; },
    { message: 'лист неподвижен', intervals: [300] }).toBe(true);
  const vw = p.viewportSize()?.width ?? 375;
  const offsets = [19, 15, 23]; // ручка листа ~19 px над заголовком (04.11: ручка y≈373 при заголовке y≈392)
  let i = 0;
  await expect(async () => {
    await p.mouse.click(vw / 2, y - offsets[i++ % offsets.length]);
    await expect.poll(async () => (await title.boundingBox())?.y ?? y, { timeout: 2_000 }).toBeLessThan(y - 20);
  }, 'лист раскрылся вверх').toPass({ timeout: 15_000 });
}
